logic:
team  = player.info.team            // PlayerState+0x930 (0 또는 1)
cache = data.cache                  // OperationData+0x0

// ── 635: 수리 필요 판정이 최우선 ────────────────────────────
match v3_epicops_repair_need(team, cache, plan) {   // u8, range 0..2
  1 => { self.objective = Some(MainObjective::Repair);   // 637: +0x41f = 7
         self.chats.push(Chat::Repair(0));               // 638: 태그 23
         return true }                                   // 639
  2 => { self.objective = Some(MainObjective::Repair);   // 642: +0x41f = 7 (채팅 없음)
         return true }                                   // 643
  _ => {}                                                // 0 이면 계속
}

// ── 651: 적이 오브젝트를 가져가는 중인가 ────────────────────
if is_object_being_taken_by_enemy(player, data, goal_data, self, /*5번째 인자*/ true) {
    // ── 652: 세르펜 경합에서 확정승인가
    if v3_serpen_contest_clear_win(version, player, data, self) {
        self.eo_serpen_punish_issues += 1;                       // 653: +0x410
        self.objective = Some(MainObjective::Serpen {            // 654: +0x41f/0x420/0x421 = 1,1,1
            phase: ObjectPhase::Setup, with_battle: true });
        self.chats.push(Chat::SerpenSetup(0));                   // 658: 태그 25
        return true;
    }
    // 확정승이 아니면 아래 압박라인 로직으로 폴스루(651 이 false 일 때와 같은 블록)
}

// ── 664 이후: '에픽 압박 라인 공지' 구간. 이 구간은 어떤 경로로 나가든 false 를 반환한다 ──
strategy   = player.strategy(rnd, cache.game);   // 664, 24B Strategy 를 스택에 sret
mu         = strategy.morgard_use;               // Strategy+0x4 를 i64 로 로드
group_line = v3_epic_group_line(mu, player, data);   // 665, Option<LineType> (i8, None=-1)
if group_line == None { return false }               // 665: v3_press_chat_line 은 건드리지 않음

if self.v3_press_chat_line == Some(group_line) { return false }   // 666: 변화 없으면 아무것도 안 함

// ── 667~671: 공지 담당자(announcer) 찾기. (0..5).find, LLVM 에서 5회 완전 언롤됨 ──
announcer: Option<usize> = (0..5).find(|&x| {
      cache.player_champion[team][x].is_some()                       // 668: null 포인터 비교
   && v3_epic_formation_role(mu, Position::from_index(x), player, data)  // 669: -> Option<V3EpicFormation>
          .is_some_and(|f| !f.is_split)                              // 670: byte0!=2 && byte0의 최하위비트==0
});
// x 순서 = Position::from_index 순서 = 0 Top / 1 Jungle / 2 Mid / 3 Bottom / 4 Support
// V3EpicFormation{ is_split: bool @+0, line: LineType @+1 } 중 line 은 여기서 안 쓴다(IR 상 poison)

// ── 672: 내가 그 담당자일 때만 채팅한다 ──
if announcer == Some(player.info.position.as_index()) {   // PlayerState+0x9c0 (as_index 인라인)
    let first = self.v3_press_chat_line.is_none();        // 673: +0x41e == -1 ?
    self.chats.push( if first { Chat::Press(group_line, 0) }        // 태그 21
                     else     { Chat::PressChange(group_line, 0) } );  // 태그 22
}

self.v3_press_chat_line = Some(group_line);   // 679: 담당자든 아니든 항상 갱신
return false;                                 // 682

// 반환값 요약: true 는 %23(repair=1) · %29(repair=2) · %56(serpen) 세 블록에서만 나온다.
// 즉 'self.objective 를 이번 호출에서 세웠는가' 이고, 압박라인 공지는 목표를 세우지 않으므로 false.
